operations.replace:
import {
  FrameConnFeatureRegistry
} from "./feature-registry-core.js";

import {
  FRAME_CONN_PLAYER_FEATURES
} from "./player_features/player-feature-registry.js";

import {
  FRAME_CONN_RULES_FEATURES
} from "./rules_features/rules-feature-registry.js";

const MODULE_TITLE =
  "Frame Conn";


/* ============================================================
   Application-wide feature composition
   ============================================================ */

/**
 * Player-facing and rules-driven packages remain independently
 * declared, but they are registered into one shared graph here so
 * required capabilities may cross the package boundary safely.
 */
export const frameConnFeatureRegistry =
  new FrameConnFeatureRegistry();

frameConnFeatureRegistry.registerMany([
  ...FRAME_CONN_PLAYER_FEATURES,
  ...FRAME_CONN_RULES_FEATURES
]);

frameConnFeatureRegistry
  .validateDependencies();


/* ============================================================
   Registered feature surfaces
   ============================================================ */

operations.search:
const registryPath =
  path.join(
    REPOSITORY_ROOT,
    "scripts",
    "player_features",
    "player-feature-registry.js"
  );


const registryText =
  textByFile.get(
    registryPath
  ) ??
  safeReadText(
    registryPath
  );


if (
  !registryText
) {
  addFinding({
    severity:
      "error",

    code:
      "FEATURE_REGISTRY_MISSING",

    message:
      "scripts/player_features/player-feature-registry.js could not be found or read.",

    file:
      registryPath
  });

  return;
}

operations.replace:
const playerRegistryPath =
  path.join(
    REPOSITORY_ROOT,
    "scripts",
    "player_features",
    "player-feature-registry.js"
  );

const rulesRegistryPath =
  path.join(
    REPOSITORY_ROOT,
    "scripts",
    "rules_features",
    "rules-feature-registry.js"
  );

const playerRegistryText =
  textByFile.get(
    playerRegistryPath
  ) ??
  safeReadText(
    playerRegistryPath
  );

const rulesRegistryText =
  textByFile.get(
    rulesRegistryPath
  ) ??
  safeReadText(
    rulesRegistryPath
  );

if (
  !playerRegistryText ||
  !rulesRegistryText
) {
  addFinding({
    severity:
      "error",

    code:
      "FEATURE_REGISTRY_MISSING",

    message:
      "Player and rules feature registries must both be present.",

    file:
      !playerRegistryText
        ? playerRegistryPath
        : rulesRegistryPath
  });

  return;
}

operations.search:
const importSpecifier =
  `./${relativePath(file).slice("scripts/player_features/".length)}`;


if (
  !registryText.includes(
    importSpecifier
  )
) {
  addFinding({
    severity:
      "warning",

    code:
      "RUNTIME_FEATURE_NOT_IMPORTED_BY_REGISTRY",

    message:
      `Runtime feature appears to declare a Frame Conn feature but is not imported by scripts/player_features/player-feature-registry.js.`,

    file,

    details: {
      expectedImport:
        importSpecifier
    }
  });
}

operations.replace:
const relative =
  relativePath(
    file
  );

const isRulesFeature =
  relative.startsWith(
    "scripts/rules_features/"
  );

const registryRoot =
  isRulesFeature
    ? "scripts/rules_features/"
    : "scripts/player_features/";

const registryText =
  isRulesFeature
    ? rulesRegistryText
    : playerRegistryText;

const registryLabel =
  isRulesFeature
    ? "scripts/rules_features/rules-feature-registry.js"
    : "scripts/player_features/player-feature-registry.js";

const importSpecifier =
  `./${relative.slice(registryRoot.length)}`;

if (
  !registryText.includes(
    importSpecifier
  )
) {
  addFinding({
    severity:
      "warning",

    code:
      "RUNTIME_FEATURE_NOT_IMPORTED_BY_REGISTRY",

    message:
      `Runtime feature appears to declare a Frame Conn feature but is not imported by ${registryLabel}.`,

    file,

    details: {
      expectedImport:
        importSpecifier,

      registry:
        registryLabel
    }
  });
}
